            [
              "Electron Energy",
              "Electrons continuously radiate energy while revolving.",
              "Electrons in stationary orbits do not radiate energy."
            ],
            [
              "Atomic Spectrum",
              "Predicted a continuous spectrum.",
              "Explains the discrete line spectrum of hydrogen atom."
            ],
            [
              "Atomic Stability",
              "Failed to explain why electrons do not collapse into the nucleus.",
              "Successfully explains the stability of the atom."
            ]
