(function layoutAtomic(){const c=DATA.chemChapters[0],s=c.topics[3].subtopics[0],t=c.tables.find(x=>x.sourcePdfPage===21);const table={...t,id:'chem9-atomic-source-table15'};table.translations=['urdu','pashto'].map(field=>({language:field==='urdu'?'اردو':'پښتو',headers:t.headers.map((v,i)=>t.interactiveTranslations?.headers?.[i]?.[field]||v),rows:t.rows.map((r,i)=>r.map((v,j)=>t.interactiveTranslations?.rows?.[i]?.[j]?.[field]||v))}));s.sourceBlocks=[table,...c.diagrams.filter(d=>d.sourcePdfPage>=22&&d.sourcePdfPage<=23).map((d,i)=>({...d,id:'chem9-atomic-source-visual-'+i}))];Object.assign(s.paras[13],{text:'Fig. 1.7 Symbolic representation of atomic number and mass number',urdu:'شکل 1.7 ایٹمی عدد اور کمیتی عدد کی علامتی نمائندگی',pashto:'شکل 1.7 د اټومي شمېرې او کتلي شمېرې نښیزه ښودنه'});s.sourceTranslationPairs=s.paras.map(p=>({...p}));s.sourceLayout=s.paras.flatMap((p,i)=>i===7?[{type:'sourceDataTable',tableId:table.id}]:[{type:'paragraph',indices:[i]},...(i===13?[{type:'visual',blockId:s.sourceBlocks[1].id}]:i===15?[{type:'visual',blockId:s.sourceBlocks[2].id}]:i===16?[{type:'visual',blockId:s.sourceBlocks[3].id}]:[])]);})();

